// Prototype keepsakes use the same progress and artwork rules in every entry.
function seedReviewStats(preset){const fresh=preset==='new',end=preset==='end';return {activeDays:fresh?1:end?536:96,itemsUsed:fresh?0:end?1208:154,focusCount:fresh?0:end?328:46,focusMinutes:fresh?0:end?8200:1150,careActions:fresh?{touch:0,feed:0,play:0,clean:0,item:0}:end?{touch:1086,feed:740,play:420,clean:240,item:0}:{touch:172,feed:106,play:64,clean:45,item:0}};}
function ensureReviewStats(){if(!S.review)S.review=seedReviewStats(S.preset||'daily');return S.review;}
function recordCare(action,amount=1){recordWish(action);S.totalCare+=amount;const review=ensureReviewStats();review.careActions[action]=(review.careActions[action]||0)+amount;}
function recordItemUse(amount=1){ensureReviewStats().itemsUsed+=amount;}
function hasMemoryArt(){return (S.unlockedCgIds||[]).includes('good_ending_year_1');}
function achievementComplete(a){return a.cg?hasMemoryArt():S.achievementProgress[a.id]>=a.target;}
function memoryCoverAsset(){return hasMemoryArt()?'cg_'+(ROLES.includes(S.role)?S.role:'furo'):(ROLES.includes(S.role)?S.role:'furo')+'_happy';}
function maybeUnlockMemory(){const review=ensureReviewStats();if(!hasMemoryArt()&&S.ageDays>=365&&S.level>=10&&review.activeDays>=200){S.unlockedCgIds=[...(S.unlockedCgIds||[]),'good_ending_year_1'];S.achievementProgress.hidden_good_ending_year_1=1;return true;}return false;}
function todayMatters(){const rows=[],ready=S.garden.filter(p=>p.state==='ready').length;
 if(S.returning&&!S.claimed.includes('return-'+S.day))rows.push(homeTodo('heart',T('好久不见，欢迎回来','Welcome home, we missed you'),S.returnDone?T('小目标完成，领取欢迎礼物','Claim your welcome gift'):wishDefinition(S.returnKind||'touch').title,'return-task'));
 if(!S.wishClaimed)rows.push(dailyWishRow());
 if(!S.neighborGifts)rows.push(neighborTodo());
 if(ready)rows.push(homeTodo('sprout',T('花园有好消息','Good news from the garden'),T(ready+' 块土地可以收获',ready+' plots are ready'),'route:garden'));
 if(S.schedulePending)rows.push(homeTodo('calendar',T('日程完成啦','Activity complete'),T('伙伴带着收获回来了','Your companion has something to share'),'route:schedule'));
 return rows.length?'<section id="today-matters" aria-labelledby="today-matters-title"><div class="section-heading"><h2 id="today-matters-title">'+T('今天的小事','Little things today')+'</h2>'+pill(String(rows.length))+'</div><div class="today-list">'+rows.join('')+'</div></section>':'';
}
function reviewContent(){const review=S.review||seedReviewStats(S.preset||'daily');const careNames={touch:T('摸摸头','Head pats'),feed:T('喂点好吃的','Tasty treats'),play:T('一起玩耍','Playtime'),clean:T('洗得香香的','A little wash'),item:T('送一份心意','Little gifts'),work:T('攒点零花钱','Part-time work')};const favorite=Object.entries(review.careActions).sort((a,b)=>b[1]-a[1])[0]||['touch',0];const best=SKILLS.slice().sort((a,b)=>S.skills[b].level-S.skills[a].level||S.skills[b].count-S.skills[a].count)[0];const stages=SKILLS.reduce((n,k)=>n+S.dreams[k].stage,0);const completed=DATA.achievements.filter(achievementComplete).length;return {name:currentName(),days:S.ageDays,level:S.level,review,best,stages,completed,favorite:{label:careNames[favorite[0]],count:favorite[1]},metrics:[
 {label:T('常来陪伴','Days together'),value:review.activeDays,unit:T('天','days'),icon:'sun',tone:'sky'},
 {label:T('照顾时刻','Care moments'),value:S.totalCare,unit:T('次','times'),icon:'heart',tone:'rose'},
 {label:T('物品使用','Items used'),value:review.itemsUsed,unit:T('件','items'),icon:'bag',tone:'gold'},
 {label:T('花园收获','Garden harvests'),value:S.harvestTotal,unit:T('次','times'),icon:'sprout',tone:'mint'},
 {label:T('完成日程','Activities done'),value:SKILLS.reduce((n,k)=>n+S.skills[k].count,0),unit:T('次','times'),icon:'calendar',tone:'sky'},
 {label:T('专注时光','Focus sessions'),value:review.focusCount,unit:T('轮','rounds'),icon:'coffee',tone:'lilac'}]};}
function yearReviewSvg(){const d=reviewContent(),colors={sky:['#e4f0ff','#3d638b'],rose:['#ffe3ed','#923f64'],gold:['#fff0b8','#7a5b22'],mint:['#e0f3e7','#3e7054'],lilac:['#eee5fb','#6e568f']};
 const text=(x,y,value,size=32,color='#334459',weight=500,extra='')=>'<text x="'+x+'" y="'+y+'" font-size="'+size+'" fill="'+color+'" font-weight="'+weight+'" '+extra+'>'+E(value)+'</text>';
 const box=(x,y,w,h,fill,rx=24)=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="'+rx+'" fill="'+fill+'"/>';
 const glyph=(name,x,y,size,color)=>'<g transform="translate('+x+' '+y+') scale('+(size/24)+')" fill="none" stroke="'+color+'" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(DATA.icons[name]||DATA.icons.flower)+'</g>';
 const artwork=(asset,x,y,w,h)=>'<image href="'+ASSETS[asset]+'" x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" preserveAspectRatio="xMidYMid meet"/>';
 const role=ROLES.includes(S.role)?S.role:'furo',title=T('一起走过的小日子','Our little days together');
 let svg='<svg xmlns="http://www.w3.org/2000/svg" width="900" height="1660" viewBox="0 0 900 1660" role="img" aria-label="'+E(title)+'" font-family="Segoe UI, Microsoft YaHei, sans-serif"><title>'+E(title)+'</title>'+box(0,0,900,1660,'#f9ead8',0)+box(25,25,850,1610,'#fffdf7',34);
 svg+='<path d="M700 25h141q34 0 34 34v108q-85 34-130-27T700 25" fill="#f9dbe5"/><path d="M25 1450q114-23 165 61t-20 124H59q-34 0-34-34Z" fill="#dceaf7"/><path d="M875 1475q-145-21-147 99l-3 61h116q34 0 34-34Z" fill="#e6dff6"/>';
 svg+=text(70,91,'POCKET · OUR MEMORY BOOK',25,'#886a55',650)+text(70,154,title,UI.lang==='en'?43:48,'#624c40',750)+box(700,62,116,24,'#ffdf88',3);
 svg+=box(68,193,764,287,'#e9f3fb',30)+'<ellipse cx="710" cy="407" rx="113" ry="38" fill="#d1e8dc"/><ellipse cx="110" cy="245" rx="74" ry="37" fill="#ffffff8f"/>';
 svg+=text(98,250,T('和 '+d.name+' 在一起','Together with '+d.name),32,'#48627b',600,d.name.length>12?'textLength="430" lengthAdjust="spacingAndGlyphs"':'');
 svg+=text(94,356,F(d.days),d.days>=100000?65:88,'#35506e',750)+text(99,403,T('天的陪伴，都是小小的珍藏','Days of little moments to treasure'),UI.lang==='en'?24:29,'#546d83',500);
 svg+=box(100,426,147,37,'#fff0bc',16)+text(118,453,'Lv.'+d.level,26,'#805d24',650)+glyph('sparkles',206,434,21,'#a98130')+artwork(role+'_happy',560,184,264,278);
 d.metrics.forEach((m,i)=>{const x=68+i%2*393,y=515+Math.floor(i/2)*165,[fill,ink]=colors[m.tone];svg+=box(x,y,371,141,fill,23)+glyph(m.icon,x+23,y+22,30,ink)+text(x+66,y+48,m.label,30,ink,600)+text(x+25,y+111,short(m.value),52,ink,750)+text(x+338,y+110,m.unit,25,ink,500,'text-anchor="end"');if(m.icon==='coffee')svg+=text(x+338,y+78,short(d.review.focusMinutes)+T(' 分钟',' min'),24,ink,500,'text-anchor="end"');});
 svg+=box(68,1037,764,168,'#fff2e7',23)+text(94,1083,T('最常做的小事','Our favorite little ritual'),29,'#8b6149',600)+text(94,1136,d.favorite.count?d.favorite.label+' × '+F(d.favorite.count):T('第一段回忆，等你来写','Our first memory is waiting'),UI.lang==='en'?32:38,'#775043',700)+text(94,1176,d.favorite.count?T('每一次回应，都让彼此靠近一点。','Every little moment brings us closer.'):T('从今天的一次摸摸开始吧。','Let’s start with a gentle head pat.'),26,'#806b60',500)+artwork('small_bouquet',697,1060,101,125);
 svg+=box(68,1231,371,183,'#edf6ee',23)+glyph('award',94,1255,31,'#527a56')+text(137,1281,T('拿手的小事','Growing skills'),30,'#436847',600)+text(94,1337,skillName(d.best)+' Lv.'+S.skills[d.best].level,36,'#395d3e',700)+text(94,1380,T('日程完成 '+S.skills[d.best].count+' 次',S.skills[d.best].count+' activities completed'),25,'#526d56');
 svg+=box(461,1231,371,183,'#efe7fa',23)+glyph('flag',487,1255,31,'#7e639c')+text(530,1281,T('成长的足迹','Little milestones'),30,'#72578e',600)+text(487,1337,T('梦想 '+d.stages+' / 20','Dream stages '+d.stages+'/20'),UI.lang==='en'?31:36,'#694f85',700)+text(487,1380,T('已达成 '+d.completed+' 项成就',d.completed+' achievements reached'),25,'#766385');
 svg+='<path d="M130 1465H770" stroke="#d9c7ad" stroke-width="3" stroke-dasharray="5 9"/><circle cx="130" cy="1465" r="9" fill="#e9b971"/><circle cx="450" cy="1465" r="9" fill="#e5abc0"/><circle cx="770" cy="1465" r="9" fill="#aaa2d6"/>';
 svg+=text(110,1511,T('从相遇开始','From hello'),27,'#826c57')+text(450,1511,T('到今天','To today'),27,'#8f6374',500,'text-anchor="middle"')+text(790,1511,T('还有许多明天','And many tomorrows'),27,'#756a92',500,'text-anchor="end"');
 svg+=text(450,1580,T('谢谢你，把普通的日子过成了喜欢的样子。','Thank you for making ordinary days feel special.'),UI.lang==='en'?27:30,'#765f50',550,'text-anchor="middle"')+'</svg>';return svg;
}
function yearReviewPoster(){const d=reviewContent(),description=T('相伴 '+d.days+' 天。','Together for '+d.days+' days. ')+d.metrics.map(m=>m.label+' '+F(m.value)+' '+m.unit).join('；');return '<figure class="year-review-poster"><img src="data:image/svg+xml;charset=utf-8,'+encodeURIComponent(yearReviewSvg())+'" width="900" height="1660" alt="'+E(description)+'"><figcaption>'+T('这些小小的数字，都是一起生活的痕迹。','Little numbers, traces of a life together.')+'</figcaption></figure>';}
function reviewSummaryMarkup(){const d=reviewContent();return '<div class="review-summary">'+d.metrics.map(m=>'<div class="review-summary-item" data-tone="'+m.tone+'"><span class="tile-icon">'+I(m.icon)+'</span><span><small>'+m.label+'</small><strong>'+F(m.value)+' <small>'+m.unit+'</small></strong></span></div>').join('')+'</div>';}
async function downloadYearReview(){const svg=yearReviewSvg(),art=new Image();await new Promise((resolve,reject)=>{art.onload=resolve;art.onerror=()=>reject(new Error('Review image could not be rendered'));art.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);});const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1660;canvas.getContext('2d').drawImage(art,0,0);const link=document.createElement('a');link.download='Pocket-year-demo.png';link.href=canvas.toDataURL('image/png');link.click();notify(T('回顾图片已生成，已请求浏览器下载。','Review image created. Download requested.'),'success');}
